-- Datos de demostración: clientes, máquinas y registros ilustrativos de
-- septiembre de 2026. Solo se cargan cuando LINEABAR_CARGAR_DEMO=1, de modo que
-- una instalación de producción no recibe registros ficticios.
-- Los UUID son fijos para que la semilla sea idempotente y reproducible.




-- Las filas de demostración ya existentes se actualizan con las horas reales.
UPDATE manutenzioni SET ore=1.5,persone=1 WHERE id='99999999-9999-4999-8999-000000000001' AND ore=0;
UPDATE manutenzioni SET ore=1,persone=1 WHERE id='99999999-9999-4999-8999-000000000002' AND ore=0;
UPDATE manutenzioni SET ore=1,persone=1 WHERE id='99999999-9999-4999-8999-000000000003' AND ore=0;
UPDATE manutenzioni SET ore=2,persone=2 WHERE id='99999999-9999-4999-8999-000000000004' AND ore=0;
UPDATE manutenzioni SET ore=1,persone=1 WHERE id='99999999-9999-4999-8999-000000000005' AND ore=0;
UPDATE manutenzioni SET ore=1.5,persone=1 WHERE id='99999999-9999-4999-8999-000000000006' AND ore=0;





-- Las tareas de demostración ya existen para estas programaciones del calendario.
UPDATE calendario_manutenzioni_macchine SET fk_attivita='bbbbbbbb-bbbb-4bbb-8bbb-000000000002' WHERE id='aaaaaaaa-aaaa-4aaa-8aaa-000000000001' AND fk_attivita IS NULL;
UPDATE calendario_manutenzioni_macchine SET fk_attivita='bbbbbbbb-bbbb-4bbb-8bbb-000000000001' WHERE id='aaaaaaaa-aaaa-4aaa-8aaa-000000000002' AND fk_attivita IS NULL;





